<map version="1.0.1"><node CREATED="1747229353087" ID="ID_root" MODIFIED="1747229353087" TEXT="指针高级"><node CREATED="1747229353087" ID="ID_396827a5f5e891c8" POSITION="right" MODIFIED="1747229353087" TEXT="动态内存分配"><node CREATED="1747229353087" ID="ID_1c2d3513068945d0" MODIFIED="1747229353087" TEXT="就是程序员自己控制内存的分配和释放。程序员控制的是堆区的内存。所以我们需要知道堆区数据的特点&amp;lt;br&amp;gt;栈区数据的特点。&amp;nbsp;有对比，才知道为什么这么选"></node><node CREATED="1747229353087" ID="ID_148c0c1eab8238fd" MODIFIED="1747229353087" TEXT="栈区特点"><node CREATED="1747229353087" ID="ID_d8fbe70fa6f0204e" MODIFIED="1747229353087" TEXT="缺点"><node CREATED="1747229353087" ID="ID_b9fe1fba6a51b128" MODIFIED="1747229353087" TEXT="小"></node><node CREATED="1747229353087" ID="ID_5e9bd8adb4492c2a" MODIFIED="1747229353087" TEXT="编译期需要确定大小"></node><node CREATED="1747229353087" ID="ID_6b0e35429c887049" MODIFIED="1747229353087" TEXT="生命周期不够长"></node></node><node CREATED="1747229353087" ID="ID_b3ab6e96b8705a91" MODIFIED="1747229353087" TEXT="优点"><node CREATED="1747229353087" ID="ID_c90c4a845dd25f20" MODIFIED="1747229353087" TEXT="使用简单、高效"></node><node CREATED="1747229353087" ID="ID_71286a8816d90cab" MODIFIED="1747229353087" TEXT="自动管理内存"></node></node></node><node CREATED="1747229353087" ID="ID_8bc8555df31494c4" MODIFIED="1747229353087" TEXT="堆区特点"><node CREATED="1747229353087" ID="ID_ac99f921247d7318" MODIFIED="1747229353087" TEXT="优点"><node CREATED="1747229353087" ID="ID_4714f3881bf676ab" MODIFIED="1747229353087" TEXT="大"></node><node CREATED="1747229353087" ID="ID_88864dbb2380df5c" MODIFIED="1747229353087" TEXT="可以运行时确定大小"></node><node CREATED="1747229353087" ID="ID_018077db1c77b552" MODIFIED="1747229353087" TEXT="生命周期可以自己控制（想申请时候申请，想释放时候释放）"></node></node><node CREATED="1747229353087" ID="ID_09ac3af443705c9e" MODIFIED="1747229353087" TEXT="缺点"><node CREATED="1747229353087" ID="ID_25db921f7490e542" MODIFIED="1747229353087" TEXT="使用麻烦。（申请、释放&amp;nbsp;稍不小心就会程序崩溃）"></node><node CREATED="1747229353087" ID="ID_dabeaf3dfed1fe14" MODIFIED="1747229353087" TEXT="效率没那么高"></node></node></node><node CREATED="1747229353087" ID="ID_fc1200177ec8f14e" MODIFIED="1747229353087" TEXT="内存使用建议"><node CREATED="1747229353087" ID="ID_a0b1689e0761418b" MODIFIED="1747229353087" TEXT="建议优先选择栈区内存"></node><node CREATED="1747229353087" ID="ID_0fc89ed98df87dc5" MODIFIED="1747229353087" TEXT="栈区内存无法满足需求，再使用堆区"><node CREATED="1747229353087" ID="ID_c0ca2c8420bef390" MODIFIED="1747229353087" TEXT="使用大内存"></node><node CREATED="1747229353087" ID="ID_685bcc53450f8605" MODIFIED="1747229353087" TEXT="编译期无法确定大小"></node><node CREATED="1747229353087" ID="ID_beb3335b0d9d1e8e" MODIFIED="1747229353087" TEXT="生命周期需要够长"></node></node><node CREATED="1747229353087" ID="ID_5ad726e7ed87b641" MODIFIED="1747229353087" TEXT="数据段是最后的选择，但用的很少"></node></node><node CREATED="1747229353087" ID="ID_4c2686edf08f084f" MODIFIED="1747229353087" TEXT="内存分配函数"><node CREATED="1747229353087" ID="ID_e5899f08a8f03fc2" MODIFIED="1747229353087" TEXT="通用指针数据类型"><node CREATED="1747229353087" ID="ID_57f06a4fa1f5c3fe" MODIFIED="1747229353087" TEXT="void *"></node><node CREATED="1747229353087" ID="ID_9adb036b70f9a8e8" MODIFIED="1747229353087" TEXT="可以用这个类型指向任意类型。其实就是存下地址"></node><node CREATED="1747229353087" ID="ID_dafb6cbf07e46de4" MODIFIED="1747229353087" TEXT="但是这个void *&amp;nbsp;不能解引用，不能算术加减"><node CREATED="1747229353087" ID="ID_7aa0cbcc85f0c801" MODIFIED="1747229353087" TEXT="int *p_int = &amp;amp;num;&amp;lt;br&amp;gt;"></node><node CREATED="1747229353087" ID="ID_26e11295e0523335" MODIFIED="1747229353087" TEXT="只能用来存地址。&amp;nbsp;"></node></node><node CREATED="1747229353087" ID="ID_c533abcd96008115" MODIFIED="1747229353087" TEXT="使用它之前，必须将其转换为正确的指针类型，才能解引用和算术加减"></node><node CREATED="1747229353087" ID="ID_82f0e113a1c7a59d" MODIFIED="1747229353087" TEXT="平常的时候，&amp;nbsp;通用指针数据类型能用，特定的指针数据类型能用。&amp;nbsp;&amp;lt;br&amp;gt;优先用特定的，因为即使用通用的，也得转换为特定的指针数据类型才能用"></node></node><node CREATED="1747229353087" ID="ID_898a11e42f677624" MODIFIED="1747229353087" TEXT="malloc/calloc/realloc/free&amp;lt;br&amp;gt;需要包含头文件 stdlib.h"></node><node CREATED="1747229353087" ID="ID_8b72121a97a5480f" MODIFIED="1747229353087" TEXT="malloc"><node CREATED="1747229353087" ID="ID_a100a3b17a1304b8" MODIFIED="1747229353087" TEXT="void* malloc(size_t size);&amp;lt;br&amp;gt;在堆区申请size个字节"></node><node CREATED="1747229353087" ID="ID_a353e07a43c7ceae" MODIFIED="1747229353087" TEXT="返回的是一个通用指针数据类型"><node CREATED="1747229353087" ID="ID_a79285635a8447e7" MODIFIED="1747229353087" TEXT="返回值有两种可能，NULL，或者一个地址"></node><node CREATED="1747229353087" ID="ID_836d5988e71905be" MODIFIED="1747229353087" TEXT="如果内存申请失败的时候，返回NULL"></node><node CREATED="1747229353087" ID="ID_3b7ba2f907f2e7e6" MODIFIED="1747229353087" TEXT="如果内存申请成功，返回首字节指针"></node></node><node CREATED="1747229353087" ID="ID_435a3536e2e351d9" MODIFIED="1747229353087" TEXT="最大的一个特点就是malloc返回的数据不会帮忙初始化，也就是我们认为里面的值是随机值。&amp;nbsp;所以在使用之前一定要进行初始化才能使用"></node><node CREATED="1747229353087" ID="ID_ccede7e759df4640" MODIFIED="1747229353087" TEXT="系统不关心底层数据是什么，&amp;nbsp;分配20个字节就是20个字节。只有程序员需要关心&amp;nbsp;&amp;lt;br&amp;gt;int *&amp;lt;br&amp;gt;char *&amp;lt;br&amp;gt;"></node></node><node CREATED="1747229353087" ID="ID_73453d78bea3121c" MODIFIED="1747229353087" TEXT="内存泄露"><node CREATED="1747229353087" ID="ID_a5ef35fb905608e5" MODIFIED="1747229353087" TEXT="如果光申请，不释放。内存肯定会耗完。&amp;lt;br&amp;gt;这个就叫内存泄露。&amp;nbsp;使用完成之后，需要释放"></node><node CREATED="1747229353087" ID="ID_20156bd8cb64b8f9" MODIFIED="1747229353087" TEXT="内存泄露"><node CREATED="1747229353087" ID="ID_b936f2d271d54cbd" MODIFIED="1747229353087" TEXT="申请内存，在使用完成之后。忘记了释放，这个就会导致本来可以被继续利用的内容，无法被别人使用，这个就叫做内存泄露&amp;lt;br&amp;gt;"></node><node CREATED="1747229353087" ID="ID_0653cc8c5fe391dc" MODIFIED="1747229353087" TEXT="泄露的解决方案是改进代码，用完要释放"></node></node><node CREATED="1747229353087" ID="ID_b3909a3edf60db4b" MODIFIED="1747229353087" TEXT="内存溢出"><node CREATED="1747229353087" ID="ID_e20b0e9d2081e6d9" MODIFIED="1747229353087" TEXT="在程序里本来就有这么多需要使用到的内存。&amp;nbsp;"></node><node CREATED="1747229353087" ID="ID_c893d43f3297c474" MODIFIED="1747229353087" TEXT="这个只能加硬件"></node></node></node><node CREATED="1747229353087" ID="ID_5728609de339ab0d" MODIFIED="1747229353087" TEXT="free"><node CREATED="1747229353087" ID="ID_915474dade26b6cd" MODIFIED="1747229353087" TEXT="void free(void *ptr);&amp;lt;br&amp;gt;将传入的指针指向的内存进行释放"></node><node CREATED="1747229353087" ID="ID_feaf61989aeb141b" MODIFIED="1747229353087" TEXT="参数必须是堆上申请内存块的地址(首字节地址)，不能传递别的指针，否则会引发未定义行为。&amp;lt;br&amp;gt;"></node><node CREATED="1747229353087" ID="ID_16ab826a87217ce4" MODIFIED="1747229353087" TEXT="使用free一些需要注意的问题"><node CREATED="1747229353087" ID="ID_87f4b3984d35002c" MODIFIED="1747229353087" TEXT="一定要传入原始的指针，也就是指针如果移动了，再传进去，这里就会报错&amp;lt;br&amp;gt;如果确实要挪，弄一个副本存一下。最后传递副本进去。&amp;nbsp;谁不挪就传谁进去"></node><node CREATED="1747229353087" ID="ID_801e92d88ad84f9c" MODIFIED="1747229353087" TEXT="不要double&amp;nbsp;free"><node CREATED="1747229353087" ID="ID_dddd9544dad62324" MODIFIED="1747229353087" TEXT="分工要明确"></node></node><node CREATED="1747229353087" ID="ID_68c04cf720c29f4f" MODIFIED="1747229353087" TEXT="悬空指针的问题"><node CREATED="1747229353087" ID="ID_e77f34a24588963e" MODIFIED="1747229353087" TEXT="int *p_int = malloc(10);&amp;lt;br&amp;gt;&amp;lt;br&amp;gt;// if&amp;lt;br&amp;gt;&amp;lt;br&amp;gt;free(p_int);&amp;lt;br&amp;gt;//&amp;nbsp;不希望出现这种情况&amp;lt;br&amp;gt;*p_int = 10;&amp;nbsp;"></node><node CREATED="1747229353087" ID="ID_a089efc91beb3538" MODIFIED="1747229353087" TEXT="一旦一个指针用完（free）之后。&amp;nbsp;建议将它的值置为NULL&amp;lt;br&amp;gt;free(p_int);&amp;lt;br&amp;gt;p_int = NULL;&amp;lt;br&amp;gt;//&amp;nbsp;&amp;lt;br&amp;gt;*p_int = 10;&amp;lt;br&amp;gt;"></node></node></node></node><node CREATED="1747229353087" ID="ID_521b566cb6ed15b2" MODIFIED="1747229353087" TEXT="calloc"><node CREATED="1747229353087" ID="ID_37e4000524b70e4d" MODIFIED="1747229353087" TEXT="在堆上申请内存，&amp;lt;br&amp;gt;void* calloc(size_t num, size_t size);&amp;lt;br&amp;gt;申请多少个内存，单个内存占多大。"></node><node CREATED="1747229353087" ID="ID_178a2969684c7f1a" MODIFIED="1747229353087" TEXT="calloc申请的内存，会初始化为0值"></node><node CREATED="1747229353087" ID="ID_57374d1e7d998890" MODIFIED="1747229353087" TEXT="其他使用基本和malloc没有区别"></node></node><node CREATED="1747229353087" ID="ID_ca4fa569311802c9" MODIFIED="1747229353087" TEXT="realloc"><node CREATED="1747229353087" ID="ID_b54311e488df1de7" MODIFIED="1747229353087" TEXT="将申请到的内存，重分配。&amp;nbsp;需要将之前获得的内存，增大一点，或者减小一点&amp;lt;br&amp;gt;void* realloc(void* ptr, size_t new_size);&amp;lt;br&amp;gt;"></node><node CREATED="1747229353087" ID="ID_ce539b680616d075" MODIFIED="1747229353087" TEXT="这个new_size是重分配之后的内存的字节数。&amp;nbsp;&amp;lt;br&amp;gt;一定不要理解成了元素的个数。&amp;nbsp;"></node><node CREATED="1747229353087" ID="ID_00553e6b45226207" MODIFIED="1747229353087" TEXT="重分配时候的细节问题"><node CREATED="1747229353087" ID="ID_dbc5aac1e67ff3bc" MODIFIED="1747229353087" TEXT="realloc重分配的时候。如果之前是40个字节，现在是60个字节。&amp;nbsp;&amp;lt;br&amp;gt;对于系统，这时候，有两种可能，一种是在原地给大家扩容&amp;lt;br&amp;gt;有另外一种可能，重新找一个新地方，把原来的数据拷贝过来。&amp;nbsp;"></node></node></node></node><node CREATED="1747229353087" ID="ID_4c30b573cfb3a59e" MODIFIED="1747229353087" TEXT="Vector"><node CREATED="1747229353087" ID="ID_85c60fb0033365f6" MODIFIED="1747229353087" TEXT="长度可变的 &amp;quot;数组&amp;quot;"><node CREATED="1747229353087" ID="ID_b394c6254060adfb" MODIFIED="1747229353087" TEXT="其实它只是底层使用了堆上的连续空间，刚开始够装，等到后面不够装的时候。&amp;nbsp;&amp;lt;br&amp;gt;这时候采取扩容策略"></node></node><node CREATED="1747229353087" ID="ID_ef347dd1cf7e11f8" MODIFIED="1747229353087" TEXT="头文件"><node CREATED="1747229353087" ID="ID_ea576acf9b17852b" MODIFIED="1747229353087" TEXT="干什么的"><node CREATED="1747229353087" ID="ID_a794a1b37ce7d345" MODIFIED="1747229353087" TEXT="装函数声明"></node><node CREATED="1747229353087" ID="ID_d13e5552e2579a28" MODIFIED="1747229353087" TEXT="结构体定义"></node><node CREATED="1747229353087" ID="ID_9e2faf7897e3f5cd" MODIFIED="1747229353087" TEXT="类型别名"></node><node CREATED="1747229353087" ID="ID_9dd0f2b9ae868703" MODIFIED="1747229353087" TEXT="宏定义"></node></node><node CREATED="1747229353087" ID="ID_d1644f6ba0d8060a" MODIFIED="1747229353087" TEXT="头文件保护性语法"><node CREATED="1747229353087" ID="ID_a9966291ba68761a" MODIFIED="1747229353087" TEXT="就是为了保证，一个头文件如果被直接或间接的包含了多次。&amp;lt;br&amp;gt;&amp;nbsp;这时候代码也能正常运行"></node></node></node><node CREATED="1747229353087" ID="ID_c65ca9178db457af" MODIFIED="1747229353087" TEXT="一定要注意。&amp;nbsp;到底是谁在底层装数据&amp;lt;br&amp;gt;vector存数据&amp;lt;br&amp;gt;还是vector-&amp;gt;table存数据？&amp;lt;br&amp;gt;扩容的时候，应该扩容table。&amp;nbsp;"></node></node></node><node CREATED="1747229353087" ID="ID_a1e11063f8b60d80" POSITION="right" MODIFIED="1747229353087" TEXT="二级指针"><node CREATED="1747229353087" ID="ID_121eaaee99b462ed" MODIFIED="1747229353087" TEXT="指针是指向某一个变量的。想修改int，可以传入int *来修改它。&amp;lt;br&amp;gt;如果想修改指针的指向呢？&amp;nbsp;&amp;lt;br&amp;gt;这时候需要二级指针"></node><node CREATED="1747229353087" ID="ID_75ba6c9a2f7100a5" MODIFIED="1747229353087" TEXT="一级指针，是指向某个数据的。&amp;nbsp;&amp;lt;br&amp;gt;"></node></node><node CREATED="1747229353087" ID="ID_81a5d91713e53194" POSITION="right" MODIFIED="1747229353087" TEXT="函数指针"><node CREATED="1747229353087" ID="ID_36d38689a9c958b0" MODIFIED="1747229353087" TEXT="函数指针，就是一个指针指向代码段上的某一片内存"></node><node CREATED="1747229353087" ID="ID_809cdbfac9716e70" MODIFIED="1747229353087" TEXT="我们传递这个指针，近似于传递一个函数"></node><node CREATED="1747229353087" ID="ID_7d01134f4af0a3de" MODIFIED="1747229353087" TEXT="qsort"><node CREATED="1747229353087" ID="ID_630a331f70fe7ced" MODIFIED="1747229353087" TEXT="什么叫大什么叫小。&amp;nbsp;&amp;lt;br&amp;gt;函数指针&amp;nbsp; &amp;nbsp;指向了某个函数"></node><node CREATED="1747229353087" ID="ID_7293f1c82b36a642" MODIFIED="1747229353087" TEXT="函数指针的一个应用"></node></node></node></node></map>